from collections import deque

def bfs(graph, start):
    seen = {start}
    queue = deque([start])
    order = []

while queue:
    node = queue.popleft()
    order.append(node)

    for nxt in graph[node]:
        if nxt not in seen:
            seen.add(nxt)
            queue.append(nxt)
return order

from collections import deque

def distance(graph, start, goal):
    seen = {start}
    queue = deque([(start, 0)])

while queue:
    node, d = queue.popleft()
    if node == goal:
        return d

    for nxt in graph[node]:
        if nxt not in seen:
            seen.add(nxt)
            queue.append((nxt, d + 1))
return -1

def dfs(graph, node, seen=None):
    if seen is None:
        seen = []
    seen.append(node)

for nxt in graph[node]:
    if nxt not in seen:
        dfs(graph, nxt, seen)
return seen

def visit(node):
    seen.add(node)
    for nxt in graph[node]:
        if nxt not in seen:
